begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1707 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2b9317ec14536ced5520b06e' and md5(to_jsonb(t)::text)='ae412a82bbfd9de99c97ac4345c80a01')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2b9317ec14536ced5520b06e';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_b86cf8ddf5843e97$[{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a las tiradas de ataque de conjuro.\n\nEl bastón tiene 50 cargas para utilizar las propiedades que se describen a continuación. Recupera 4d6 + 2 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 20, el bastón recupera 1d12 + 1 cargas.\n\nAbsorción de conjuros. Mientras empuñes el bastón, tendrás ventaja en las tiradas de salvación contra conjuros. Además, puedes usar tu reacción cuando otra criatura lance un conjuro que solo te haga objetivo a ti. Si lo haces, el bastón absorberá la magia del conjuro, cancelará su efecto y obtendrá una cantidad de cargas igual al nivel del conjuro absorbido. No obstante, si esto hace que la cantidad total de cargas del bastón supere las 50, el bastón explotará como si hubieses activado su golpe vengador (consulta más adelante).\n\nConjuros. Mientras empuñes el bastón, puedes usar una acción y gastar algunas de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y aptitud mágica: abrir (2 cargas), bola de fuego (versión de nivel 7, 7 cargas), conjurar elemental (7 cargas), desplazamiento entre planos (7 cargas), disipar magia (3 cargas), esfera de llamas (2 cargas), invisibilidad (2 cargas), muro de fuego (4 cargas), pasamuros (5 cargas), relámpago (versión de nivel 7, 7 cargas), telaraña (2 cargas), telequinesis (5 cargas) o tormenta de hielo (4 cargas).\n\nTambién puedes usar una acción para lanzar uno de los siguientes conjuros desde el bastón sin gastar ninguna carga: agrandar/reducir, cerradura arcana, detectar magia, luz, mano de mago o protección contra el bien y el mal.\n\nGolpe vengador. Puedes usar una acción para romper el bastón de un rodillazo o contra una superficie sólida, lo que ejecuta un golpe vengador. El bastón se destruye y libera la magia que le queda a modo de explosión que se extiende para cubrir una esfera de 9 m de radio centrada en él.\n\nTienes un 50 por ciento de probabilidad de viajar en ese instante a un plano de existencia aleatorio y evitar la explosión. Si no logras evitar el efecto, sufrirás una cantidad de daño de fuerza igual a 16 veces el número de cargas del bastón. Todas las demás criaturas situadas en esa zona deberán hacer una tirada de salvación de Destreza con CD 17. Si la fallan, sufrirán daño conforme a la distancia a la que se encuentren del punto de origen, tal y como se muestra en la siguiente tabla. Si la superan, recibirán la mitad de ese daño.\n\n3 m de distancia o más · 8 veces el número de cargas\ncerca · del bastón\nDe 4 m a 6 m de · 6 veces el número de cargas\ndistancia · del bastón\nDe 7 m a 9 m de · 4 veces el número de cargas\ndistancia · del bastón\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a las tiradas de ataque de conjuro.\n\nEl bastón tiene 50 cargas para utilizar las propiedades que se describen a continuación. Recupera 4d6 + 2 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 20, el bastón recupera 1d12 + 1 cargas.\n\nAbsorción de conjuros. Mientras empuñes el bastón, tendrás ventaja en las tiradas de salvación contra conjuros. Además, puedes usar tu reacción cuando otra criatura lance un conjuro que solo te haga objetivo a ti. Si lo haces, el bastón absorberá la magia del conjuro, cancelará su efecto y obtendrá una cantidad de cargas igual al nivel del conjuro absorbido. No obstante, si esto hace que la cantidad total de cargas del bastón supere las 50, el bastón explotará como si hubieses activado su golpe vengador (consulta más adelante).\n\nConjuros. Mientras empuñes el bastón, puedes usar una acción y gastar algunas de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y aptitud mágica: abrir (2 cargas), bola de fuego (versión de nivel 7, 7 cargas), conjurar elemental (7 cargas), desplazamiento entre planos (7 cargas), disipar magia (3 cargas), esfera de llamas (2 cargas), invisibilidad (2 cargas), muro de fuego (4 cargas), pasamuros (5 cargas), relámpago (versión de nivel 7, 7 cargas), telaraña (2 cargas), telequinesis (5 cargas) o tormenta de hielo (4 cargas).\n\nTambién puedes usar una acción para lanzar uno de los siguientes conjuros desde el bastón sin gastar ninguna carga: agrandar/reducir, cerradura arcana, detectar magia, luz, mano de mago o protección contra el bien y el mal.\n\nGolpe vengador. Puedes usar una acción para romper el bastón de un rodillazo o contra una superficie sólida, lo que ejecuta un golpe vengador. El bastón se destruye y libera la magia que le queda a modo de explosión que se extiende para cubrir una esfera de 9 m de radio centrada en él.\n\nTienes un 50 por ciento de probabilidad de viajar en ese instante a un plano de existencia aleatorio y evitar la explosión. Si no logras evitar el efecto, sufrirás una cantidad de daño de fuerza igual a 16 veces el número de cargas del bastón. Todas las demás criaturas situadas en esa zona deberán hacer una tirada de salvación de Destreza con CD 17. Si la fallan, sufrirán daño conforme a la distancia a la que se encuentren del punto de origen, tal y como se muestra en la siguiente tabla. Si la superan, recibirán la mitad de ese daño.\n\n3 m de distancia o más · 8 veces el número de cargas\ncerca · del bastón\nDe 4 m a 6 m de · 6 veces el número de cargas\ndistancia · del bastón\nDe 7 m a 9 m de · 4 veces el número de cargas\ndistancia · del bastón\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b86cf8ddf5843e97$::jsonb,true),'{rules,personalDescription}',$text_8b9b4248e9d7e0fc$"Este bastón puede ser usado como un bastón mágico que otorga un bonificador +2 a las tiradas de ataque y daño realizadas con él. Mientras lo sostienes, obtienes un bonificador +2 a las tiradas de ataque con conjuros. El bastón tiene 50 cargas para las siguientes propiedades. Recupera 4d6 + 2 cargas gastadas diariamente al amanecer. Si gastas la última carga, tira 1d20. Con un 20, el bastón recupera 1d12 + 1 cargas.\n\n-Absorción de hechizos. Mientras sostienes el bastón, tienes ventaja en las tiradas de salvación contra hechizos. Además, puedes usar tu reacción cuando otra criatura lanza un hechizo que solo te afecta a ti. Si lo haces, el bastón absorbe la magia del hechizo, cancelando su efecto y obteniendo una cantidad de cargas igual al nivel del hechizo absorbido. Sin embargo, si al hacerlo, la cantidad total de cargas del bastón supera las 50, el bastón explota como si hubieras activado su ataque vengativo (ver más abajo).\n\n-Conjuros. Mientras sostienes el bastón, puedes usar una acción para gastar algunas de sus cargas y lanzar uno de los siguientes conjuros desde él, usando tu CD de salvación de conjuros y tu aptitud para lanzar conjuros: conjurar elemental (7 cargas), disipar magia (3 cargas), bola de fuego (versión de nivel 7, 7 cargas), esfera llameante (2 cargas), tormenta de hielo (4 cargas), invisibilidad (2 cargas), derribo (2 cargas), rayo (versión de nivel 7, 7 cargas), atravesar muro (5 cargas), desplazamiento de plano (7 cargas), telequinesis (5 cargas), muro de fuego (4 cargas) o telaraña (2 cargas). También puedes usar una acción para lanzar uno de los siguientes conjuros desde el bastón sin usar ninguna carga: bloqueo arcano, detectar magia, agrandar/reducir, luz, mano de mago o protección contra el mal y el bien.\n\n-Golpe vengativo. Puedes usar una acción para romper el bastón sobre tu rodilla o contra una superficie sólida, realizando un golpe vengativo. El bastón se destruye y libera su magia restante en una explosión que se expande para llenar una esfera de 30 pies de radio centrada en él. Tienes un 50 por ciento de probabilidad de viajar instantáneamente a un plano de existencia aleatorio, evitando la explosión. Si no logras evitar el efecto, recibes daño de fuerza igual a 16 × el número de cargas en el bastón. Todas las demás criaturas en el área deben realizar una tirada de salvación de Destreza CD 17. Si falla la tirada de salvación, una criatura recibe una cantidad de daño basada en lo lejos que está del punto de origen, como se muestra en la siguiente tabla. Si tiene éxito, una criatura recibe la mitad de daño.\n\nA 10 pies de distancia o más cerca: 8 veces el número de cambios en el personal\nDe 11 a 20 pies de distancia - 6 veces el número de cambios en el personal\nDe 21 a 30 pies de distancia - 4 veces la cantidad de cargas en el personal"$text_8b9b4248e9d7e0fc$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2b9317ec14536ced5520b06e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2bc2a95f6395e248236a47ab' and md5(to_jsonb(t)::text)='f22e3fd0279fe516d153f29e61323d9c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2bc2a95f6395e248236a47ab';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_3d20682e3808f6a0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para soplar este cuerno. Como respuesta, varios espíritus guerreros del Valhalla aparecerán a 18 m o menos de ti. Utilizan el perfil del berserker. Regresarán al Valhalla después de 1 hora o cuando sus puntos de golpe se reduzcan a 0. Una vez que utilices el cuerno, no podrás volver a usarlo hasta que hayan pasado 7 días.\n\nSe conoce la existencia de cuatro tipos de cuerno del Valhalla, cada uno hecho de un metal distinto. El tipo de cuerno determina cuántos berserkers responden a su llamada, así como el requisito para utilizarlo. Tu GM elige el tipo de cuerno o lo determina al azar.\n\n01–40 · Plata · 2d4 + 2 · Ninguno\n41–75 · Oropel · 3d4 + 3 · Competencia con todas las armas sencillas\n76–90 · Bronce · 4d4 + 4 · Competencia con todas las armaduras medias\n91–00 · Hierro · 5d4 + 5 · Competencia con todas las armas marciales\n\nSi soplas el cuerno sin cumplir su requisito, los berserkers invocados te atacarán. Si cumples el requisito, serán amistosos contigo y tus compañeros, y seguirán tus órdenes.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3d20682e3808f6a0$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2bc2a95f6395e248236a47ab';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2bda57073d4de65a9fc99b84' and md5(to_jsonb(t)::text)='44bbd9bda902ab6804a574e79f6482dc')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2bda57073d4de65a9fc99b84';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_2268b2509e814df7$[{"id":"official-use","kind":"passive","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este amuleto, permanecerás oculto ante la magia de adivinación. No podrás ser objetivo de ningún efecto mágico de ese tipo ni podrán percibirte mediante sensores mágicos de escudriñamiento.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_2268b2509e814df7$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2bda57073d4de65a9fc99b84';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2ce971dab6d5fa7c121bc193' and md5(to_jsonb(t)::text)='4dd272d48586cec93fb9f2cd892cf225')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2ce971dab6d5fa7c121bc193';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_aaf89e7b6a02353d$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto del conjuro acelerar durante 1 minuto (no requiere concentración). El líquido amarillo de este brebaje tiene vetas negras y forma remolinos.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_aaf89e7b6a02353d$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2ce971dab6d5fa7c121bc193';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2d00d208f92c4357d88f466e' and md5(to_jsonb(t)::text)='45c4654d53997f3900a69366dc5ecf7c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2d00d208f92c4357d88f466e';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_fc57461b72b10b78$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes utilizar una acción para pronunciar la palabra de activación de la alfombra y hacer que levite y vuele. Se moverá según las indicaciones verbales que le des, siempre y cuando estés a 9 m o menos de distancia de ella.\n\nExisten cuatro tamaños de alfombra voladora. TU GM elige el tamaño o lo determina al azar.\n\n01–20 90 cm × 1,5 m ·  · 100 kg · 24 m\n21–55 1,2 m × 1,8 m ·  · 200 kg · 18 m\n56–80 1,5 m × 2,1 m ·  · 300 kg · 12 m\n81–100 1,8 m × 2,7 m ·  · 400 kg · 9 m\n\nLa alfombra puede transportar hasta el doble del peso mostrado en la tabla, pero vuela a la mitad de su velocidad si transporta un peso superior a su capacidad normal.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_fc57461b72b10b78$::jsonb,true),'{rules,personalDescription}',$text_85837eb743374cd1$"Puedes utilizar una acción para pronunciar la palabra de activación de la alfombra y hacer que levite y vuele. Se moverá de acuerdo a tus instrucciones verbales, siempre que permanezcas a 30 pies de ella. Existen cuatro tamaños de alfombra voladora. El DM elige el tamaño o lo determina al azar.\n\n3 ft. x 5 ft. - 200 lb. - 80 feet\n4 ft. x 6 ft. - 400 lb. - 60 feet\n5 ft. x 7 ft. - 600 lb. - 40 feet\n6 ft. x 9 ft. - 800 lb. - 30 feet\nLa alfombra puede cargar hasta dos veces el peso mostrado en la tabla, pero volará a la mitad de velocidad si transporta un peso superior a su capacidad normal (la indicada en Ja tabla)."$text_85837eb743374cd1$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2d00d208f92c4357d88f466e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2d32f4a1dfeb0a52c48095f1' and md5(to_jsonb(t)::text)='b227aa4dddded985ce81c3d09dd39d04')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2d32f4a1dfeb0a52c48095f1';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_3b91126f195b264e$"Objeto · Precio base · Peso\nÁcido (vial) · 25 po · 1 lb\n\nÁcido. Como acción, puedes esparcir el contenido de este vial sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el vial se rompa con el impacto. En ambos casos, haz un ataque a distancia contra una criatura u objeto y trata el ácido como un arma improvisada. Si impacta, el objetivo sufre 2d6 de daño de ácido.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_3b91126f195b264e$::jsonb,true),'{features}',$text_03a33af9cb8863f0$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Ácido. Como acción, puedes esparcir el contenido de este vial sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el vial se rompa con el impacto. En ambos casos, haz un ataque a distancia contra una criatura u objeto y trata el ácido como un arma improvisada. Si impacta, el objetivo sufre 2d6 de daño de ácido.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_03a33af9cb8863f0$::jsonb,true),'{rules,definition,description}',$text_a405f1f3fe336dd6$[{"id":"official-table","rows":[["Ácido (vial)","25 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Ácido. Como acción, puedes esparcir el contenido de este vial sobre una criatura que esté a 1,5 m o menos de ti o lanzarlo hasta a 6 m, lo que hará que el vial se rompa con el impacto. En ambos casos, haz un ataque a distancia contra una criatura u objeto y trata el ácido como un arma improvisada. Si impacta, el objetivo sufre 2d6 de daño de ácido.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$text_a405f1f3fe336dd6$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_bb21ed74d2f9e9dc$["official-table","official-rules-0"]$text_bb21ed74d2f9e9dc$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2d32f4a1dfeb0a52c48095f1';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2d37f163346ec0dd009ba51d' and md5(to_jsonb(t)::text)='fbefeb0b8282ae19e56890ba30056f5c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2d37f163346ec0dd009ba51d';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_c177eb09f8c78bc3$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2d37f163346ec0dd009ba51d';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2ff65e228901f70ca8f98828' and md5(to_jsonb(t)::text)='c591aac74608316bb06cf4bce7e980b3')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:2ff65e228901f70ca8f98828';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_6a176a5460d3e0d9$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa y tengas la capucha puesta, las pruebas de Sabiduría (Percepción) que se hagan para verte tendrán desventaja y tú tendrás ventaja en las pruebas de Destreza (Sigilo) que hagas para esconderte, ya que el color de la capa cambia para camuflarte. Ponerte o quitarte la capucha requiere una acción.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_6a176a5460d3e0d9$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:2ff65e228901f70ca8f98828';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:30656091b999872276793afc' and md5(to_jsonb(t)::text)='08724168c0e9581b0b088703cf9aa30e')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:30656091b999872276793afc';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_ff5772d0bc461b80$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta esfera de hierro oxidada mide 7,5 cm de diámetro y pesa 0,5 kg. Puedes usar una acción para pronunciar la palabra de activación y lanzar la esfera contra una criatura Enorme o más pequeña que puedas ver a 18 m o menos de ti. En el recorrido del lanzamiento, la esfera se abre en una maraña de bandas de metal.\n\nRealiza una tirada de ataque a distancia con un bonificador de ataque igual a tu modificador por Destreza más tu bonificador por competencia. Si impactas, el objetivo quedará apresado hasta que utilices una acción adicional para volver a pronunciar la palabra de activación y liberarlo. Si haces esto o si el ataque yerra, las bandas se contraerán y volverán a convertirse en una esfera.\n\nCualquier criatura, incluida la que está apresada, puede emplear una acción para realizar una prueba de Fuerza con CD 20 y romper las bandas de hierro. Si la supera, el objeto se destruye y la criatura apresada se libera. Si la falla, cualquier otro intento de romper las bandas por parte de la criatura fallará automáticamente hasta que hayan transcurrido 24 horas.\n\nUna vez que se utilizan las bandas, no podrán volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ff5772d0bc461b80$::jsonb,true),'{rules,personalDescription}',$text_1bb60076cee99854$"Esta pequeña esfera ele hierro oxidado miele 3 pulgadas de diámetro y pesa una libra. Puedes usar una acción para pronunciar la palabra de activación y lanzar la esfera contra una criatura que puedas ver, se encuentre a 60 pies o menos ele ti y sea Enorme o más pequeña. Durante el recorrido del lanzamiento. la esfera se abre en una maraña ele bandas de metal.\n\nRealiza una tirada de ataque con un bonificador igual a tu modificador de Destreza más tu bonificador por competencia. Si impactas, el objetivo queda apresado hasta que utilices una acción adicional para pronunciar de nuevo la palabra de activación y liberarle. S i haces esto, o si el ataque falla, las bandas se contraen de nuevo y se vuelven a convertir en una esfera.\n\nCualquier criatura, incluyendo la que está apresada, puede emplear una acción para realizar una prueba de Fuerza CD 20 y romper las bandas de hierro. Si tiene éxito, el objeto queda destruido y la criatura apresada se libera. Si falla, cualquier otro intento de romper las bandas que haga esa criatura durante las próximas 24 horas fallará automáticamente."$text_1bb60076cee99854$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:30656091b999872276793afc';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:31e133f12be930aa336bc88c' and md5(to_jsonb(t)::text)='7a294569518abcdb3d575d5bad653eac')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:31e133f12be930aa336bc88c';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_bbdf4b4486601b3b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este yelmo tiene 3 cargas. Mientras lo lleves puesto, podrás utilizar una acción y gastar 1 carga para lanzar el conjuro teletransporte desde él. El yelmo recupera 1d3 cargas empleadas cada día, al amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_bbdf4b4486601b3b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:31e133f12be930aa336bc88c';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:34cbbbaf34a6ecc0fd73e8ca' and md5(to_jsonb(t)::text)='279bb2ba79561888fd87ea01d7c06520')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:34cbbbaf34a6ecc0fd73e8ca';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_c177eb09f8c78bc3$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:34cbbbaf34a6ecc0fd73e8ca';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3534fedcf685dcdcbdddaa6c' and md5(to_jsonb(t)::text)='e6532a826eb8f81cce95329b4d695081')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:3534fedcf685dcdcbdddaa6c';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_05f5187d34948d72$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este calzado ligero, podrás moverte hacia arriba, hacia abajo y de lado por superficies verticales, así como boca abajo por techos. Esta manera de moverse no requiere del uso de las manos, que quedan libres. Tienes una velocidad trepando igual a tu velocidad caminando. No obstante, las babuchas no te permiten desplazarte de esta forma por una superficie resbaladiza, como una zona cubierta por hielo o aceite.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_05f5187d34948d72$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3534fedcf685dcdcbdddaa6c';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:35b4956012293b51dbd948f2' and md5(to_jsonb(t)::text)='dc54a1e93c575cefe14fff45f3ee5502')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:35b4956012293b51dbd948f2';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_47ab4ab81b1e6ae0$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta pesada bolsa de tela contiene 3d4 judías blancas. La bolsa pesa 250 g más 125 g por cada judía que contenga.\n\nSi tiras el contenido de la bolsa al suelo, explotará en un radio de 3 m alrededor de las judías. Todas las criaturas situadas en la zona, incluyéndote a ti, deberán realizar una tirada de salvación de Destreza con CD 15; sufrirán 5d4 de daño de fuego si la fallan o la mitad del daño si la superan. Los objetos inflamables de la zona arderán siempre y cuando no los lleve o vista alguien.\n\nSi sacas una judía de la bolsa, la plantas en tierra o arena y la riegas, la judía producirá un efecto 1 minuto después en el suelo donde la hayas plantado. Tu GM puede elegir el efecto de la siguiente tabla, determinarlo al azar o crear uno nuevo.\n\n01 · Brotan 5d4 hongos venenosos. Si una criatura come un hongo, tira un dado. Si el resultado es impar, la criatura deberá superar una tirada de salvación de Constitución con CD 15 o recibirá 5d6 de daño de veneno y quedará envenenada durante 1 hora. Si el resultado es par, la criatura obtendrá 5d6 puntos de golpe temporales que durarán 1 hora.\n02–10 · Un géiser emerge del suelo y expulsa a borbotones agua, cerveza, zumo de bayas, té, vinagre, vino o aceite (a elección de tu GM). El chorro tiene una altura de 9 m y dura 1d12 asaltos.\n11–20 · Un ent brota del suelo. Hay un 50 % de probabilidad de que sea caótico malvado y ataque.\n21–30 · Surge una estatua de piedra animada e inmóvil con tu apariencia que te amenaza verbalmente. Si la abandonas y otros se acercan, la estatua te describirá como el más vil de los villanos y mandará a los recién llegados a buscarte y atacarte. Si estás en el mismo plano de existencia que la estatua, sabrá donde estás. La estatua se volverá inanimada al cabo de 24 horas.\n31–40 · Surge una hoguera de llamas azules que arderá durante 24 horas (o hasta que la apaguen).\n41–50 · 1d6 + 6 chillones brotan del suelo.\n51–60 · 1d4 + 8 sapos de color rosa intenso salen del suelo. Si alguien toca uno de los sapos, este se transforma en un monstruo Grande o más pequeño a elección de tu GM. El monstruo permanece durante 1 minuto y luego desaparece en una nube de humo rosa intenso.\n61–70 · Un bulette hambriento sale de la tierra y ataca.\n71–80 · Crece un árbol frutal. Tiene 1d10 + 20 piezas de fruta, de las cuales 1d8 tienen los efectos de pociones determinadas al azar y otra de ellas funciona como un veneno ingerido a elección de tu GM. El árbol se desvanece tras 1 hora. La fruta recogida permanece y conserva la magia durante 30 días.\n81–90 · Aparece un nido con 1d4 + 3 huevos. Cualquier criatura que se coma uno de estos huevos deberá realizar una tirada de salvación de Constitución con CD 20. Si la supera, aumentará su puntuación de característica más baja en 1 de forma permanente (se elegirá al azar la puntuación si hay varias puntuaciones que empatan como la más baja). Si la falla, la criatura recibirá 10d6 de daño de fuerza debido a una explosión mágica interna.\n91–99 · Una pirámide con una base cuadrada de 18 m de lado emerge del suelo. En el interior hay un sarcófago que contiene a un señor de las momias. La pirámide se considera la guarida del señor de las momias y su sarcófago alberga un tesoro a elección de tu GM.\n00 · Brota un tallo de judías gigante que crece hasta la altura que decida tu GM, que también elige adónde conduce la parte superior. Por ejemplo, podría dar a un hermoso mirador, al castillo de un gigante de las nubes o a otro plano de existencia.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_47ab4ab81b1e6ae0$::jsonb,true),'{rules,personalDescription}',$text_32b6e00d588a05c4$"Dentro de esta pesada bolsa de tela hay 3d4 judías secas. La bolsa pesa 1/2 libra, más 1/4 de libra adicional por cada judía que contenga. Si vacías el contenido de la bolsa en el suelo, este explotará en un radio de 10 pies alrededor de las judías. Todas las criaturas que se encuentren en el área deberá n hacer una tirada de salvación de Destreza CD 15, sufriendo 5d4 de daño de fuego si la fallan, o la mitad de ese daño si la superan. Los objetos en el área que no lleve o vista alguien arderán. Si coges una judía de la bolsa, la plantas en tierra o arena y la riegas, producirá un efecto en el suelo 1 minuto después de ser plantada. El DM puede escoger un efecto de la siguiente tabla, determinarlo al azar o crear uno nuevo.\n01 - Brotan Sd4 hongos venenosos. Si una criatura come uno de estos hongos, tira un dado. Si el resultado es impar, la criatura deberá superar una tirada de salvación de Constitución CD 15 o recibirá Sd6 de daño de veneno y quedará envenenada durante 1 hora. Con un resultado par, la criatura ganará 5d6 puntos de golpe temporales que duran una hora.\n 02- 10 Un géiser surge del suelo, expulsando a borbotones agua, cerveza, zumo de bayas, té, vinagre, vino o aceite (a elección del DM). El chorro tiene una altura de 30 pies y dura ldl2 asaltos. \n11-20 - Del suelo brota un ent (su perfil está en el Monster Manual). Hay un 50 % de probabilidades de que esta criatura sea caótica malvada y ataque inmediatamente. \n21-30 - Aparece una estatua de piedra animada e inmóvil con tu apariencia. Te amenazará verbalmente. Si la abandonas y otros se acercan, la estatua te describirá como el más vil de los villanos y mandará a los recién llegados a buscarte y atacarte. Si estás en el mismo plano de existencia que la estatua, sabrá donde estás. Se volverá inanimada tras 24 horas.\n31-40 - Surge una hoguera de llamas azules, que arderá durante 24 horas (o hasta que sea extinguida).\n41-50 - Brotan del suelo l d6 + 6 chillones (ver el perfil en el Monster Manual).\n51-60 - Se arrastrarán, saliendo de entre la tierra, 1d4 + 8 sapos de color rosa brillante. Cuando se toque a uno, este se convertirá en un monstruo Grande o más pequeño a elección del DM. El monstruo permanecerá durante l minuto y después desaparecerá en una nube de humo rosa brillante.\n61-70 - Un bulette hambriento (ver el perfil en el Monster Manual) sale excavando de la tierra y ataca. \n71-80 - Un árbol frutal crece rápidamente en el sitio. Tiene 1d10 + 20 piezas de fruta, de las cuales 1d8 se comportan como pociones determinadas aleatoriamente y otra de ellas como un veneno ingerido a elección del DM. El árbol se desvanece en una hora. La fruta que haya sido recogida permanece y la magia se mantiene durante 30 días.\n81-90 - Aparece un nido con ld4 + 3 huevos. Cualquier criatura que coma uno de estos huevos deberá realizar una tirada de salvación de Constitución CD 20. Si tiene éxito, incrementará su puntuación de característica más baja en 1, eligiendo al azar si hay varias puntuaciones empatadas por ser la más baja. Si fa lla, la criatura recibirá 10d6 de daño de fuerza de una explosión mágica interna.\n91-99 - Una pirámide con una base de 60 pies cuadrados surge del suelo. Dentro hay un sarcófago con un señor de las momias en su interior (ver el perfil en el Monster Manual). La pirámide se considera la guarida del señor de las momias y su sarcófago contiene un tesoro a elección del DM.\n00 - Brota un tallo de judía gigante, que crece hasta la altura que el DM considere oportuno. La parte más alta da acceso a un sitio también a su elección, ya sea el castillo de un gigante de las nubes, una hermosa vista u otro plano de existencia."$text_32b6e00d588a05c4$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:35b4956012293b51dbd948f2';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:372fde0046c3e7c354b9b95a' and md5(to_jsonb(t)::text)='62a22e124a4c8a76d8d60ae4eaee4887')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:372fde0046c3e7c354b9b95a';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_5e2c0c85cd829724$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta cuerda mide 9 m de largo y pesa 1,5 kg. Si sujetas uno de los extremos de la cuerda y utilizas una acción para pronunciar su palabra de activación, el otro extremo saldrá disparado hacia delante para enredar a una criatura que puedas ver a 6 m o menos de ti. El objetivo deberá superar una tirada de salvación de Destreza con CD 15 o quedará apresado.\n\nPuedes liberar a la criatura si usas una acción adicional para pronunciar una segunda palabra de activación. Un objetivo apresado por la cuerda puede utilizar una acción para realizar una prueba de Fuerza o Destreza (a elección del objetivo) con CD 15. Si la supera, la criatura dejará de estar apresada.\n\nLa cuerda tiene una CA de 20 y 20 puntos de golpe. Recupera 1 punto de golpe cada 5 minutos mientras tenga al menos 1 punto de golpe. Si los puntos de golpe de la cuerda se reducen a 0, se destruye.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5e2c0c85cd829724$::jsonb,true),'{rules,personalDescription}',$text_4bebd670c254d07f$"Esta cuerda tiene 30 pies de largo y pesa 3 libras. S i sostienes un extremo de la cuerda y utilizas una acción para pronunciar su palabra de activación, el otro extremo saldrá volando para enredar a una criatura que puedas ver y que se encuentre a 20 pies o menos de ti. Esta criatura deberá superar una tirada de salvación de Destreza CD 15 o quedará apresada.\n\nPuedes liberar a la criatura empleando una acción adicional para pronunciar la segunda palabra de activación. Una criatura apresada por la cuerda puede usar su acción para realizar una prueba de Fuerza o Destreza (a su elección) con CD 15. Si tiene éxito, dejará de estar apresada.\n\nLa cuerda posee CA 20 y 20 puntos de golpe. Recupera 1 punto de golpe cada 5 minutos, mientras tenga al menos 1 punto de golpe. Si los puntos de golpe de la cuerda descienden a O, queda destruida."$text_4bebd670c254d07f$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:372fde0046c3e7c354b9b95a';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:38070df72830c84b3b5c4bea' and md5(to_jsonb(t)::text)='116ca78a1072a3dc62651262c817be40')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:38070df72830c84b3b5c4bea';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_c177eb09f8c78bc3$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:38070df72830c84b3b5c4bea';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3873f56f6673d7d6a8e03ffb' and md5(to_jsonb(t)::text)='ee0cbfa1295581ca5e80cceed92f62e4')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:3873f56f6673d7d6a8e03ffb';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_28be7e6ab30b84f7$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás el efecto del conjuro detectar pensamientos (CD de salvación 13). En el líquido denso y morado de la poción flota una nube rosa ovoide.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_28be7e6ab30b84f7$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3873f56f6673d7d6a8e03ffb';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:39453ee81afcebaacb6be012' and md5(to_jsonb(t)::text)='180d4ad2d462b48b63c09e20e4cef4cb')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:39453ee81afcebaacb6be012';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_f210f5b75e2cfc57$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta delicada tela negra, suave como la seda, está doblada para tener las dimensiones de un pañuelo. Al desdoblarla, se convierte en una sábana circular de 1,8 m de diámetro.\n\nPuedes utilizar una acción para extender un agujero portátil y colocarlo sobre una superficie sólida o apoyado en ella, donde creará un agujero extradimensional de 3 m de profundidad. El espacio cilíndrico en el interior del agujero se encuentra en otro plano, así que no sirve para crear pasadizos. Cualquier criatura que esté en el interior de un agujero portátil abierto podrá salir de él escalando.\n\nPuedes utilizar una acción para cerrar un agujero portátil sujetando los bordes de la tela y doblándola. Al doblar la tela se cierra el agujero y cualquier criatura u objeto que haya en su interior permanecerá en el espacio extradimensional. Independientemente de su contenido, el agujero no pesa casi nada.\n\nSi se dobla, las criaturas que haya dentro del espacio extradimensional del agujero podrán utilizar una acción para realizar una prueba de Fuerza con CD 10. Si la superan, se abrirán paso hacia la salida y aparecerán a 1,5 m o menos del agujero portátil o de la criatura que lo lleve consigo. Si se mete dentro del agujero portátil a una criatura que necesite respirar, podrá sobrevivir durante 10 minutos; después, empezará a ahogarse.\n\nMeter un agujero portátil en el espacio extradimensional creado por una bolsa de contención, un morral práctico o un objeto similar destruye instantáneamente ambos objetos y abre un portal al Plano Astral. El portal se crea en el sitio en el que un objeto se introdujo dentro del otro. El portal absorbe a todas las criaturas que estén a 3 m o menos de él y las conduce a un lugar aleatorio del Plano Astral. Después, el portal se cierra. El portal solo funciona en un sentido y no puede volverse a abrir.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f210f5b75e2cfc57$::jsonb,true),'{rules,personalDescription}',$text_0f00e0363fa566bd$"Esta delicada tela negra, suave como la seda, está doblada hasta ocupar el espacio de un pañuelo. Se despliega en una sábana circular de 6 pies de diámetro.\nPuedes usar una acción para extender un agujero portátil y colocarlo en una superficie sólida, donde creará un hueco extradimensional de 10 pies de profundidad. El espacio cilíndrico en el que existe el agujero está en otro plano, por lo que no puede emplearse para crear pasadizos. Una criatura dentro de un agujero portátil puede salir del agujero escalando.\nPuedes utilizar una acción para cerrar un agujero portátil cogiendo los bordes de la tela y doblándola. Plegarla cierra el agujero, de modo que las criaturas u objetos que estuvieran dentro permanecerán ahí. Independientemente de su conte nido, el agujero no pesa nada.\nSi este se pliega, una criatura situada dentro del espacio extradimensional podrá usar una acción para hacer una prueba de Fuerza CD 10. Si tiene éxito, consigue salir a la fuerza y aparece en un espacio a 5 pies del agujero o de la criatura que lo lleve consigo. Si una criatura que necesite respirar es colocada dentro, podrá sobrevivir durante 10 minutos, tras lo cual empieza a ahogarse.\nPoner un agujero portátil dentro del espacio extradimensional creado por un morral práctico de Heward, bolsa de contención u otro objeto similar destruye instantáneamente ambos objetos y abre un portal al Plano Astral. Se creará en el sitio donde un objeto se metió dentro del otro. Cualquier criatura que se encuentre a 10 pies del portal será absorbida a través de este a una localización aleatoria en el Plano Astral. Después, el portal se cierra. Solo funciona en un sentido y no puede ser reabierto."$text_0f00e0363fa566bd$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:39453ee81afcebaacb6be012';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:397f56a255aa64b959bb17ad' and md5(to_jsonb(t)::text)='774345f74f5334c662a5cf89d51cca93')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:397f56a255aa64b959bb17ad';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_bdb52a76377c1eea$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando ataques a un objeto con esta espada mágica e impactes, toma el resultado máximo de los dados de daño del arma contra el objetivo.\n\nCuando ataques a una criatura con esta arma y saques un 20 en la tirada de ataque, el objetivo sufrirá 4d6 de daño cortante adicional. A continuación, tira otro d20. Si sacas un 20, seccionarás uno de los miembros del objetivo. Tu GM determinará el efecto de esta amputación. Si la criatura no tiene ningún miembro que se pueda amputar, en vez de ello, seccionarás otra parte de su cuerpo.\n\nAdemás, puedes pronunciar la palabra de activación de la espada para hacer que la hoja emita luz brillante en un radio de 3 m y luz tenue 3 m más allá. Si vuelves a pronunciar la palabra de activación o envainas la espada, apagarás la luz.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_bdb52a76377c1eea$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:397f56a255aa64b959bb17ad';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:399d2fabfaca062f022b9259' and md5(to_jsonb(t)::text)='4f64c9130ca353b415446e9b5c2975ff')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:399d2fabfaca062f022b9259';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_b0fdb5e9b42a7c29$[{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b0fdb5e9b42a7c29$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:399d2fabfaca062f022b9259';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:39e88b4040a225d6baa7b634' and md5(to_jsonb(t)::text)='96bf16f8776df67149e5d46ac29faa13')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:39e88b4040a225d6baa7b634';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_30771ecbb5fe20fa$[{"id":"official-base-table","rows":[["Maza","5 po","4 lb","1d6 contundente","+0","—"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_30771ecbb5fe20fa$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_6834d0d967473cf4$["official-base-table","family-rule"]$text_6834d0d967473cf4$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:39e88b4040a225d6baa7b634';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3a1cacc0e24f2e0b2016270d' and md5(to_jsonb(t)::text)='cd3dc254d585f6a5af5c2e78707f22ab')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:3a1cacc0e24f2e0b2016270d';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_961876d4f1b87a7e$[{"id":"official-base-table","rows":[["Pico de guerra","5 po","2 lb","1d8 perforante","+0","—"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_961876d4f1b87a7e$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_6834d0d967473cf4$["official-base-table","family-rule"]$text_6834d0d967473cf4$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3a1cacc0e24f2e0b2016270d';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3a81c2f6a557d09b39518381' and md5(to_jsonb(t)::text)='c28f676fec45cb9d73fe1ab6a3ec595e')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:3a81c2f6a557d09b39518381';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_3041fc769c486f0c$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta bolsa guarda un parecido superficial con una bolsa de contención, pero en realidad es el orificio de alimentación de una criatura extradimensional gigante. Poner la bolsa del revés cierra el orificio.\n\nLa criatura extradimensional vinculada a la bolsa puede sentir cualquier cosa que se meta en su interior y devora cualquier materia animal o vegetal que se introduzca por completo. Esta materia se pierde para siempre. Cuando se introduce parte de una criatura viva en la bolsa, como cuando alguien mete la mano, hay un 50 % de probabilidad de que toda la criatura se vea arrastrada al interior. Una criatura que esté dentro de la bolsa puede utilizar su acción para tratar de escapar superando una prueba de Fuerza con CD 15. Otra criatura puede utilizar su acción para meter la mano en la bolsa con el fin de sacar a una criatura, lo que logrará si supera una prueba de Fuerza con CD 20 (siempre y cuando no vaya a parar ella también al interior de la bolsa primero). Cualquier criatura que comience su turno en el interior de la bolsa será devorada y su cuerpo será destruido.\n\nSe pueden guardar objetos inanimados en la bolsa, que puede albergar 0,03 m3 de dicho material. No obstante, una vez al día, la bolsa se traga cualquier objeto que contenga y lo escupe en otro plano de existencia. Tu GM determina el momento y el plano.\n\nSi se perfora o se rasga la bolsa, se destruye y cualquier cosa que contenga se transporta a un lugar aleatorio del Plano Astral.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3041fc769c486f0c$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3a81c2f6a557d09b39518381';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3b1581c937cbc58988d337c0' and md5(to_jsonb(t)::text)='b863b5bfed6ab1b8140d9b4902ac98a3')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:3b1581c937cbc58988d337c0';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_f90f6a78613d875c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes a un infernal o muerto viviente con esta arma mágica, esa criatura recibirá 2d6 de daño radiante adicional. Si al objetivo le quedan 25 puntos de golpe o menos tras sufrir este daño, deberá superar una tirada de salvación de Sabiduría con CD 15 o será destruido. Si la supera, la criatura quedará asustada de ti hasta el final de tu siguiente turno.\n\nMientras empuñes esta arma, emitirá luz brillante en un radio de 6 m y luz tenue 6 m más allá.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f90f6a78613d875c$::jsonb,true),'{rules,personalDescription}',$text_d26e14df57c76560$"Cuando golpeas a un Demonio o a un No Muerto con esta arma mágica, esa criatura recibe 2d6 puntos de daño Radiante adicionales. Si el objetivo tiene 25 Puntos de Golpe o menos después de recibir este daño, debe superar una tirada de salvación de Sabiduría CD 15 o será destruido. Si la tirada de salvación tiene éxito, la criatura tiene el estado de Asustado hasta el final de tu siguiente turno.\n\nLuz. Mientras sostienes esta arma, emite Luz brillante en un radio de 20 pies y Luz tenue en otros 20 pies. La competencia con una maza te permite sumar tu bonificación por competencia a la tirada de ataque de cualquier ataque que realices con ella."$text_d26e14df57c76560$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3b1581c937cbc58988d337c0';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3b8581124ebb69e0130f882e' and md5(to_jsonb(t)::text)='024ed2f8680087ea3f12e61cb22059c0')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:3b8581124ebb69e0130f882e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_49e3e80c25fd1c94$[{"id":"lance-special","kind":"other","name":"Uso de la lanza de caballería","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Lanza de caballería. Tendrás desventaja si usas una lanza de caballería para atacar a un objetivo que esté a 1,5 m o menos de ti. Además, si no estás sobre una montura, necesitarás las dos manos para empuñarla.\n\nRequiere dos manos si no se está montado.\n\nDuración: Mientras se utiliza el arma..","showInActions":false}]$text_49e3e80c25fd1c94$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3b8581124ebb69e0130f882e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3ba334460d1fc2fa2a8a2a56' and md5(to_jsonb(t)::text)='7d59e331b3e7884be4f28b7701a07825')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:3ba334460d1fc2fa2a8a2a56';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_a5e60adaef5e7214$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta bolsa de aspecto ordinario, hecha de tela de color gris, rojizo o marrón, parece vacía. No obstante, meter la mano en su interior revela la presencia de un objeto pequeño y peludo. La bolsa pesa 250 g.\n\nPuedes usar una acción para sacar el objeto peludo de la bolsa y lanzarlo a 6 m o menos de distancia. Cuando aterrice, se transformará en la criatura que determines al tirar 1d8 y consultar la tabla que corresponda al color de la bolsa. La criatura desaparecerá al siguiente amanecer o cuando sus puntos de golpe se reduzcan a 0.\n\nLa criatura es amistosa contigo y tus compañeros y actúa en tu turno. Puedes emplear una acción adicional para decirle cómo debe moverse y qué acción debe realizar en su turno o para darle órdenes más generales, como atacar a tus enemigos. Si no recibe tales órdenes, se comportará conforme a su naturaleza.\n\nUna vez que se han extraído tres objetos peludos de la bolsa, no puede volver a utilizarse hasta el siguiente amanecer. Bolsa de trucos gris\n\n1 · Comadreja\n2 · Rata gigante\n3 · Tejón\n4 · Jabalí\n5 · Pantera\n6 · Tejón gigante\n7 · Lobo terrible\n8 · Alce gigante\n\nBolsa de trucos rojiza\n\n1 · Rata\n2 · Búho\n3 · Mastín\n4 · Cabra\n5 · Cabra gigante\n6 · Jabalí gigante\n7 · León\n8 · Oso pardo\n\nBolsa de trucos marrón\n\n1 · Chacal\n2 · Simio\n3 · Babuino\n4 · Pico de hacha\n5 · Oso negro\n6 · Comadreja gigante\n7 · Hiena gigante\n8 · Tigre\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_a5e60adaef5e7214$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3ba334460d1fc2fa2a8a2a56';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3c51a3c091c8f10097310716' and md5(to_jsonb(t)::text)='3ae6e1d1cf3fde91c5fc7bd216384018')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:3c51a3c091c8f10097310716';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_908dfa734a103f7e$"Objeto · Precio base · Peso\nPetate · 1 po · 7 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_908dfa734a103f7e$::jsonb,true),'{rules,definition,description}',$text_31b34ce008f3ab23$[{"id":"official-table","rows":[["Petate","1 po","7 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_31b34ce008f3ab23$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3c51a3c091c8f10097310716';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3d024672d426c959fbf7c9a1' and md5(to_jsonb(t)::text)='d402d80188351224c3b20708bda4566d')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:3d024672d426c959fbf7c9a1';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_a48bd797ee9953ab$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este tubo contiene un líquido lechoso con un fuerte olor a alcohol. Puedes utilizar una acción para verter el contenido del tubo en una superficie que esté a tu alcance. El líquido disolverá de manera instantánea hasta 0,1 m2 de adhesivo que toque, incluido el pegamento soberano.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_a48bd797ee9953ab$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:3d024672d426c959fbf7c9a1';
